/**
 * The Witch Trial — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { WITCH_TRIAL_TEMPLATE } from '../witch-trial';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Witch Trial — template structure", () => {
  it('carries its identity', () => {
    expect(WITCH_TRIAL_TEMPLATE.id).toBe('encounter.town.witch_trial');
    expect(WITCH_TRIAL_TEMPLATE.reach).toBe('veil');
    expect(WITCH_TRIAL_TEMPLATE.rarityTier).toBe(2);
    expect(WITCH_TRIAL_TEMPLATE.steps).toHaveLength(3);
  });

  it('step 0 deals the authored hand', () => {
    const step = WITCH_TRIAL_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['witch.settle_frightened_breath', 'witch.uncover_true_spirit']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['life', 'spirit']);
  });

  it('step 1 deals the authored hand', () => {
    const step = WITCH_TRIAL_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['witch.remember_wet_harvest', 'witch.quicken_hidden_rot']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['entropy', 'mind']);
  });

  it('step 2 deals the authored hand', () => {
    const step = WITCH_TRIAL_TEMPLATE.steps[2];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['witch.silence_angry_square', 'witch.wake_old_gratitude']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['mind', 'order']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(WITCH_TRIAL_TEMPLATE.settings).toEqual(['urban']);
    expect(WITCH_TRIAL_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(WITCH_TRIAL_TEMPLATE.consequenceDraw).toEqual(['relationship', 'secret']);
    expect(WITCH_TRIAL_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.witch_trial',
          reach: 'veil',
          rarityTier: 2,
        }),
        WITCH_TRIAL_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
